    'help.faq.privateQ': 'How do I make my account private?',
    'help.faq.privateA': 'Open Settings → Privacy and turn on “Private account”. Only approved followers will then be able to see your profile.',
    'help.faq.notifQ': 'I’m not receiving notifications.',
    'help.faq.notifA': 'In Settings → Notifications, make sure “Push notifications” is on. If it stays off, enable notifications for ',
    'help.faq.passwordQ': 'How do I reset my password?',
    'help.faq.passwordA': 'Go to Settings → Account → Change password. We’ll email a verification code you can use to set a new password.',
    'help.faq.sellQ': 'How do I sell on the marketplace?',
    'help.faq.sellA': 'Tap Marketplace in the top bar, then Sell to add a product. Buyers pay you directly using the M-Pesa, till or bank details you list on each product.',
    'help.faq.dataQ': 'How do I reduce data usage?',
    'help.faq.dataA': 'In Settings → Playback & Data, turn on “Data saver”, switch off “Autoplay videos”, and set Audio quality to “Data saver”.',
    'help.faq.contactQ': 'How do I contact the team?',
    'help.faq.contactA': 'Use “Contact admins” in Settings to send a private message, or email us using the button below.',
    'help.topic.bible': 'Bible, quiz & puzzle',
    'help.faq.forgotQ': 'I forgot my password and can’t sign in.',
    'help.faq.forgotA': 'On the sign-in screen tap “Forgot password?”, enter your email, and we’ll send a code you can use to choose a new password.',
    'help.faq.devicesQ': 'How do I sign out of another phone?',
    'help.faq.devicesA': 'Open Settings → Devices signed in. Every phone or browser you are signed in on is listed there; tap Sign out next to any you don’t recognise.',
    'help.faq.quietQ': 'Can I stop notifications at night?',
    'help.faq.quietA': 'Yes. In Settings, turn on Quiet hours and choose when they start and end. Security messages still come through.',
    'help.faq.offlineQ': 'How do I listen to music without internet?',
    'help.faq.offlineA': 'Tap the download icon on a song. Your saved songs are in Downloads and play with no connection. Downloads can be set to happen on Wi-Fi only in Settings.',
    'help.faq.storageQ': 'The app is using a lot of space on my phone.',
    'help.faq.storageA': 'Open Settings → Storage. You can remove all downloaded songs, or clear saved pages — copies kept so screens open quickly, which come back as you use the app.',
    'help.faq.publishQ': 'How do I publish a book or study?',
    'help.faq.publishA': 'Open Publishing from the menu and tap Write. Add chapters one at a time — a chapter stays a draft, seen only by you, until you publish it.',
    'help.faq.serviceQ': 'How do I list my business or service?',
    'help.faq.serviceA': 'Open Services from the menu and tap Add Listing. Add what you offer, where you are, your prices and hours. A tick on a listing means it has been verified.',
    'help.faq.versionQ': 'How do I change the Bible version or language?',
    'help.faq.versionA': 'In the Bible, choose a version from the cards at the top — English, Kiswahili, Dholuo and more. The app remembers your choice.',
    'help.faq.notesQ': 'Where are my highlights, notes and bookmarks?',
    'help.faq.notesA': 'All of them are in My Bible, together with your favourite verses and reading history. Search them, or tap one to open it at its verse.',
    'help.faq.widgetQ': 'How do I put the verse of the day on my home screen?',
    'help.faq.widgetA': 'On Android, touch and hold an empty part of your home screen, choose Widgets, and add “Verse of the Day”. It shows the same verse as the app.',
    'help.faq.dailyQuizQ': 'Why can I play the daily quiz only once?',
    'help.faq.dailyQuizA': 'Everyone gets the same twenty questions and is ranked on them, so each person plays once. A new quiz is drawn each morning. Practice — Speed, Streak and by section — has no limit.',
    'help.faq.battleQ': 'How do I run a Bible Battle for my group?',
    'help.faq.battleA': 'In Bible Quiz, choose Host to start a room. Everyone else chooses Join and types the six-letter code you show them. Start when everyone is in — the whole room answers each question together.',
    'help.faq.coinsQ': 'How do I get more coins in the Word Puzzle?',
    'help.faq.coinsA': 'You earn coins by finding words. Spend them on a hint when you are stuck.',
    'help.faq.payQ': 'How do I pay for something I bought?',
    'help.faq.payA': 'You pay each seller directly — by M-Pesa, till or bank — using the details shown on your order, and arrange delivery with them. The seller confirms once your payment arrives.',
    'help.faq.ordersQ': 'Where can I see my orders?',
    'help.faq.ordersA': 'Open Market and tap My orders to follow each one, from payment to delivery.',
    'help.emailUnavailable': 'Email is not set up on this device.',
