    // ── User Guide ──────────────────────────────────────────────────────────
    'guide.title': 'How to use Adventist Life',
    'guide.subtitle': 'A quick tour of everything you can do',
    'guide.intro': 'New here? This guide walks through each part of the app — how to share, listen, connect and worship together. Read from the top, or jump to the section you need.',
    'guide.feed.title': 'Social Feed & Stories',
    'guide.feed.body': 'The feed is your community timeline: For You, with Explore beside it for trending posts, hashtags and people to follow. Tap + to post photos, videos and testimonies — tag people with @, add #hashtags, choose who can see it, or keep it as a draft. Comments open in a sheet where you can reply, react and mention. Share a Story that disappears after 24 hours, and tap the video button in the top bar to watch videos full screen, one after another.',
    'guide.music.title': 'Music',
    'guide.music.body': 'The Music page has charts of what is played most, new releases, music from artists you follow and genres to browse. Search finds songs, artists, albums and playlists even with a typo. Build playlists in your Library, download songs to listen offline, and open Now Playing for the full player. Playback keeps going while you use the rest of the app and on the lock screen. Artists and choirs can upload songs and whole albums.',
    'guide.hymns.title': 'Hymnals',
    'guide.hymns.body': 'Open Hymns in the top bar to sing from the hymnals in four languages. Find a hymn by its number or title, and save favourites to keep the ones you are learning or singing this Sabbath close at hand — sort them however suits you.',
    'guide.bible.title': 'Bible',
    'guide.bible.body': 'Read the Bible in English, Kiswahili, Dholuo and more — choose a version from the cards at the top. Tap a verse to highlight it, add a note, keep it as a favourite or share it, and bookmark chapters to come back to. Jesus’s words are shown in red. Everything you keep is in My Bible, where you can search it and open any entry at its verse.',
    'guide.verse.title': 'Verse of the Day',
    'guide.verse.body': 'One verse each day, the same for everyone. Listen to it, read the whole chapter, keep it in My Bible, or share it as a picture or as text. Your streak counts the days in a row you have read it. On Android you can also add the verse to your home screen as a widget.',
    'guide.publishing.title': 'Publishing',
    'guide.publishing.body': 'Read and publish long-form writing: books, studies and devotionals, one chapter at a time. The reader keeps your place, works offline, and lets you change the text size and theme, highlight and discuss each chapter. Writers start with Write, can invite co-authors, and see how their books are read in the Author Studio. Join a book club to read one book together on a plan.',
    'guide.quiz.title': 'Bible Quiz',
    'guide.quiz.body': 'Play the daily quiz — twenty questions, the same for everyone, ranked on today’s, this week’s and all-time boards. Practise with Speed or Streak, or by section of the Bible, and questions you miss come back for review. Tap Why? for the answer explained from Scripture. Challenge a friend to a duel, or host a Live Bible Battle where a whole room answers together. Your progress shows your streak, badges and strongest books.',
    'guide.puzzle.title': 'Word Puzzle',
    'guide.puzzle.body': 'Drag across the wheel of letters to spell words that appear in Scripture and fill the board. Stuck? Spend coins on a hint. Play the Daily Puzzle — the same board for everyone — carry on level by level, or choose a theme, winning up to three stars each time. Tap a word you found to see what it means, and challenge a friend to beat your time. The puzzle plays in Kiswahili too.',
    'guide.communities.title': 'Communities',
    'guide.communities.body': 'Communities are where people gather — a church, a choir, a news circle, or anything you start yourself. Browse by category or search, then request to join one to unlock its private chat. Inside you can send messages, photos, documents and voice notes in real time, react with emojis, swipe a message to reply, and search the whole conversation. Admins can pin a message, add moderators and manage members. Starting your own takes a name and a category — and if no category fits, you can create that too.',
    'guide.groups.title': 'Groups',
    'guide.groups.body': 'Create or join interest groups for Bible study, youth, prayer and more. Groups have the full realtime chat with typing indicators, who is online, pinned messages and an activity log. Private groups can ask a question before letting someone in, and admins choose who is allowed to post.',
    'guide.messages.title': 'Direct Messages',
    'guide.messages.body': 'Tap a member to start a private conversation. Direct messages support text, photos, files and voice notes, show when your message has been read, and let you reply and react just like the group chats.',
    'guide.live.title': 'Live Events',
    'guide.live.body': 'Watch services and events streamed live, or go live yourself to broadcast to the community. Join a live room to watch and chat along in real time.',
    'guide.services.title': 'Services',
    'guide.services.body': 'A directory of what people in the community offer — media studios, hospitality, health, professional services, home and trades. Search by name, place or service. Each service has its own page with prices, opening hours, a gallery, reviews and directions, and you can call, WhatsApp or message them in the app. A tick shows a verified service. List your own, take bookings and see how your page is doing.',
    'guide.market.title': 'Marketplace',
    'guide.market.body': 'Open Market in the top bar to browse what people are selling by category, or search. Add items to your cart or wishlist and check out. You pay each seller directly — by M-Pesa, till or bank, using the details on their product — and arrange delivery with them; follow every order in My orders. Want to sell? Tap Sell Your Products to list one and manage your orders from the seller dashboard.',
    'guide.notices.title': 'Notice Board',
    'guide.notices.body': 'The Notice Board carries official announcements for everyone, pinned ones first — news, events and important updates. You can also send the admins a private note from the board.',
    'guide.tools.title': 'Calendar, Weather & Calculator',
    'guide.tools.body': 'Under Tools in the menu. The calendar marks every Sabbath with its sunset times and keeps your own entries and reminders on your phone. Weather shows today and the week ahead for your town. The calculator shows the answer as you type.',
    'guide.account.title': 'Your Account & Settings',
    'guide.account.body': 'Tap your profile to edit your details and see your posts. In Settings you can switch between English and Kiswahili, turn the background pictures on or off, choose your notifications and quiet hours, see and sign out the devices you are signed in on, and free up storage. The Privacy Centre explains your privacy controls, and Help answers common questions.',
    'guide.footerTip': 'Tip: open the menu any time from the ☰ icon in the top corner to jump between features.',

