    'guide.singles.title': 'Single & Searching',
    'guide.singles.body': 'A separate, opt-in space for unmarried adults (18 and over) to meet with marriage in mind. Every profile is checked by our team before anyone sees it. Home suggests people you may connect with — and says why — with New, Nearby and Online to browse. Tap Interested or Not now; when you are both interested it’s a match, with ideas to begin, a get-to-know-you game, and your chat in Messages. Join the singles community’s questions, meet-ups and live voice rooms, verify your photo for the tick, and choose who can see you. Pause or leave any time, and report or block anyone from any screen.',
    'help.faq.singlesJoinQ': 'Who can join Single & Searching?',
    'help.faq.singlesJoinA': 'Unmarried adults aged 18 and over, with a verified email and an account at least a week old. Your profile is reviewed before others can see it, usually within a day.',
