    'help.faq.privateQ': 'Ninawezaje kufanya akaunti yangu kuwa ya faragha?',
    'help.faq.privateA': 'Fungua Mipangilio → Faragha na uwashe “Akaunti ya faragha”. Wafuasi walioidhinishwa pekee ndio wataweza kuona wasifu wako.',
    'help.faq.notifQ': 'Sipokei arifa.',
    'help.faq.notifA': 'Katika Mipangilio → Arifa, hakikisha “Arifa za push” zimewashwa. Kama zinabaki zimezimwa, ruhusu arifa za ',
    'help.faq.passwordQ': 'Ninawezaje kuweka upya nywila yangu?',
    'help.faq.passwordA': 'Nenda Mipangilio → Akaunti → Badilisha nywila. Tutakutumia msimbo wa uthibitisho kwa barua pepe ambao unaweza kutumia kuweka nywila mpya.',
    'help.faq.sellQ': 'Ninawezaje kuuza kwenye soko?',
    'help.faq.sellA': 'Gusa Soko kwenye upau wa juu, kisha Uza ili kuongeza bidhaa. Wanunuzi wanakulipa moja kwa moja kwa kutumia M-Pesa, till au maelezo ya benki unayoorodhesha kwa kila bidhaa.',
    'help.faq.dataQ': 'Ninawezaje kupunguza matumizi ya data?',
    'help.faq.dataA': 'Katika Mipangilio → Uchezaji na Data, washa “Kiokoa data”, zima “Cheza video kiotomatiki”, na uweke Ubora wa sauti kuwa “Kiokoa data”.',
    'help.faq.contactQ': 'Ninawezaje kuwasiliana na timu?',
    'help.faq.contactA': 'Tumia “Wasiliana na wasimamizi” katika Mipangilio kutuma ujumbe wa faragha, au tutumie barua pepe kwa kutumia kitufe kilicho hapa chini.',
    'help.topic.bible': 'Biblia, maswali na fumbo',
    'help.faq.forgotQ': 'Nimesahau nywila yangu na siwezi kuingia.',
    'help.faq.forgotA': 'Kwenye skrini ya kuingia gusa “Umesahau nywila?”, weka barua pepe yako, nasi tutakutumia nambari ya kuchagua nywila mpya.',
    'help.faq.devicesQ': 'Ninawezaje kutoka kwenye simu nyingine?',
    'help.faq.devicesA': 'Fungua Mipangilio → Vifaa vilivyoingia. Kila simu au kivinjari ulichoingia nacho kimeorodheshwa hapo; gusa Toka kando ya chochote usichokitambua.',
    'help.faq.quietQ': 'Ninaweza kusimamisha arifa usiku?',
    'help.faq.quietA': 'Ndiyo. Katika Mipangilio, washa Saa za utulivu na uchague zinapoanza na kuisha. Ujumbe wa usalama bado utafika.',
    'help.faq.offlineQ': 'Ninawezaje kusikiliza muziki bila mtandao?',
    'help.faq.offlineA': 'Gusa ikoni ya kupakua kwenye wimbo. Nyimbo ulizohifadhi ziko kwenye Vilivyopakuliwa na hucheza bila mtandao. Katika Mipangilio unaweza kuweka upakuaji ufanyike kwa Wi-Fi pekee.',
    'help.faq.storageQ': 'Programu inatumia nafasi kubwa kwenye simu yangu.',
    'help.faq.storageA': 'Fungua Mipangilio → Hifadhi. Unaweza kuondoa nyimbo zote ulizopakua, au kufuta kurasa zilizohifadhiwa — nakala zinazofanya skrini zifunguke haraka, ambazo hurudi unapotumia programu.',
    'help.faq.publishQ': 'Ninawezaje kuchapisha kitabu au funzo?',
    'help.faq.publishA': 'Fungua Uchapishaji kutoka kwenye menyu na ugusa Andika. Ongeza sura moja moja — sura hubaki rasimu, inayoonekana kwako pekee, hadi uichapishe.',
    'help.faq.serviceQ': 'Ninawezaje kuorodhesha biashara au huduma yangu?',
    'help.faq.serviceA': 'Fungua Huduma kutoka kwenye menyu na ugusa Ongeza Orodha. Weka unachotoa, ulipo, bei zako na saa za kazi. Alama ya tiki kwenye orodha inamaanisha imethibitishwa.',
    'help.faq.versionQ': 'Ninawezaje kubadilisha toleo au lugha ya Biblia?',
    'help.faq.versionA': 'Katika Biblia, chagua toleo kutoka kadi zilizo juu — Kiingereza, Kiswahili, Dholuo na zaidi. Programu hukumbuka chaguo lako.',
    'help.faq.notesQ': 'Rangi, madokezo na alama zangu ziko wapi?',
    'help.faq.notesA': 'Vyote viko kwenye Biblia Yangu, pamoja na mistari unayoipenda na historia ya kusoma. Vitafute, au gusa kimoja kukifungua kwenye mstari wake.',
    'help.faq.widgetQ': 'Ninawezaje kuweka mstari wa siku kwenye skrini yangu ya nyumbani?',
    'help.faq.widgetA': 'Kwenye Android, gusa na ushikilie sehemu tupu ya skrini ya nyumbani, chagua Wijeti, na uongeze “Verse of the Day”. Inaonyesha mstari ule ule ulio kwenye programu.',
    'help.faq.dailyQuizQ': 'Kwa nini naweza kucheza maswali ya kila siku mara moja tu?',
    'help.faq.dailyQuizA': 'Kila mtu hupata maswali ishirini yale yale na hupangwa kwa matokeo yake, kwa hiyo kila mtu hucheza mara moja. Maswali mapya huchaguliwa kila asubuhi. Mazoezi — Kasi, Mfululizo na kwa sehemu — hayana kikomo.',
    'help.faq.battleQ': 'Ninawezaje kuendesha Pambano la Biblia kwa kikundi changu?',
    'help.faq.battleA': 'Katika Maswali ya Biblia, chagua Ongoza kuanzisha chumba. Wengine wote huchagua Jiunge na kuandika nambari ya herufi sita unayowaonyesha. Anza kila mtu akishaingia — chumba kizima hujibu kila swali pamoja.',
    'help.faq.coinsQ': 'Ninawezaje kupata sarafu zaidi kwenye Fumbo la Maneno?',
    'help.faq.coinsA': 'Unapata sarafu kwa kutafuta maneno. Zitumie kupata kidokezo unapokwama.',
    'help.faq.payQ': 'Ninalipaje kwa nilichonunua?',
    'help.faq.payA': 'Unamlipa kila muuzaji moja kwa moja — kwa M-Pesa, till au benki — ukitumia maelezo yaliyo kwenye oda yako, na mnapanga usafirishaji pamoja. Muuzaji huthibitisha malipo yako yakifika.',
    'help.faq.ordersQ': 'Naweza kuona oda zangu wapi?',
    'help.faq.ordersA': 'Fungua Soko na ugusa Oda zangu kufuatilia kila moja, kuanzia malipo hadi kufika.',
    'help.emailUnavailable': 'Barua pepe haijawekwa kwenye kifaa hiki.',
