    'adminSingles.unbanBody': 'Wasifu wake unarudi kuwa rasimu ya kukaguliwa.',
    'guide.singles.title': 'Single & Searching',
    'guide.singles.body': 'Eneo tofauti, la hiari, kwa watu wazima wasiooa wala kuolewa (miaka 18 na zaidi) kukutana kwa nia ya ndoa. Kila wasifu hukaguliwa na timu yetu kabla mtu yeyote kuuona. Nyumbani hupendekeza watu unaoweza kuendana nao — na kueleza kwa nini — pamoja na Wapya, Karibu na Mtandaoni kuvinjari. Gusa Navutiwa au Si sasa; mkivutiwa wote wawili mmelingana, pamoja na mawazo ya kuanza, mchezo wa kujuana, na mazungumzo yenu kwenye Ujumbe. Shiriki maswali ya jamii ya waseja, mikutano na vyumba vya sauti, thibitisha picha yako upate tiki, na uchague nani anaweza kukuona. Sitisha au ondoka wakati wowote, na ripoti au zuia mtu yeyote kutoka skrini yoyote.',
    'help.faq.singlesJoinQ': 'Nani anaweza kujiunga na Single & Searching?',
    'help.faq.singlesJoinA': 'Watu wazima wasiooa wala kuolewa wa miaka 18 na zaidi, wenye barua pepe iliyothibitishwa na akaunti ya angalau wiki moja. Wasifu wako hukaguliwa kabla wengine kuuona, kwa kawaida ndani ya siku moja.',
    'help.faq.singlesSafeQ': 'Ninawezaje kuwa salama kwenye Single & Searching?',
    'help.faq.singlesSafeA': 'Zungumzeni ndani ya programu hadi umwamini mtu, usitume pesa kamwe, na kutaneni kwanza mahali pa wazi. Tumia Ripoti au zuia kwenye wasifu au mlinganisho wowote — wasimamizi hukagua kila ripoti — na Ondoa mlinganisho hufunga mazungumzo kwa nyote wawili.',
